// One item per active WooCommerce client. Downstream nodes then run once per
// client through n8n's native per-item execution, the same shape wf_shopify uses.
const dec = b64 => Buffer.from(b64, 'base64').toString('utf8').trim();

const clients = $('Read active Woo clients').all();
const bases   = $('Get base_url').all();
const keys    = $('Get consumer_key').all();
const secrets = $('Get consumer_secret').all();

// A length mismatch means one client is missing a secret. Fail loudly rather
// than pairing the wrong shop's credentials to the wrong client_id.
for (const [label, arr] of [['base-url', bases], ['consumer-key', keys], ['consumer-secret', secrets]]) {
  if (arr.length !== clients.length) {
    throw new Error('Secret fetch mismatch: ' + clients.length + ' active clients but ' + arr.length + ' ' + label + ' results. Check Secret Manager for woocommerce-<slug>-' + label + '.');
  }
}

return clients.map((c, i) => {
  const ck = dec(keys[i].json.payload.data);
  const cs = dec(secrets[i].json.payload.data);
  return {
    json: {
      client_id: c.json.client_id,
      slug:      c.json.slug,
      currency:  c.json.currency,
      timezone:  c.json.timezone || 'Europe/Prague',
      base_url:  dec(bases[i].json.payload.data).replace(/\/+$/, ''),
      // WooCommerce only honours consumer_key/consumer_secret as query
      // parameters over plain HTTP. Over HTTPS it wants HTTP Basic Auth, and
      // answers 401 woocommerce_rest_cannot_view otherwise.
      auth_b64: Buffer.from(ck + ':' + cs).toString('base64')
    },
    pairedItem: { item: i }
  };
});

const INGESTED_AT = new Date().toISOString();

// BigQuery refuses invalid UTF-8 outright, and a control character or an
// unpaired surrogate in a product name, city or email would fail a row.
//
// This is deliberately written as a charCodeAt scan rather than a regex: the
// previous version was a character class of \u escape sequences, the escaping
// did not survive being stored on the node, and the class degraded into
// literal characters -- the letter u, every digit, the colon and A-Z -- which
// it then stripped out of every string it touched. Corrupted 1979 rows before
// it was caught. No escape sequences here means no escaping layer can break it.
const clean = v => {
  if (v === null || v === undefined) return null;
  const s = String(v);
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 9 || c === 10 || c === 13) { out += s[i]; continue; }  // tab, LF, CR are fine
    if (c < 32 || c === 127) continue;                               // other C0 controls are not
    if (c >= 0xD800 && c <= 0xDBFF) {                                // high surrogate
      const n = s.charCodeAt(i + 1);
      if (n >= 0xDC00 && n <= 0xDFFF) { out += s[i] + s[i + 1]; i++; continue; }  // valid pair, keep
      continue;                                                      // unpaired, drop
    }
    if (c >= 0xDC00 && c <= 0xDFFF) continue;                        // stray low surrogate
    out += s[i];
  }
  return out;
};

// BigQuery rejects NaN and Infinity; NUMERIC carries a scale of 9, so values
// are rounded well inside it.
const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n * 1e6) / 1e6 : null;
};
const sum = (arr, pick) => {
  let t = 0;
  for (const x of (arr || [])) {
    const n = Number(pick(x));
    if (Number.isFinite(n)) t += n;
  }
  return Math.round(t * 1e6) / 1e6;
};

// WooCommerce on HPOS can emit PHP zero-dates like '-0001-11-30T00:00:00',
// which parse to a real Date in year -1 and are refused by BigQuery.
const parseTs = v => {
  if (!v) return null;
  const raw = String(v).trim();
  if (!raw || raw.startsWith('0000') || raw.startsWith('-')) return null;
  const d = new Date(/[Zz]$/.test(raw) ? raw : raw + 'Z');
  if (isNaN(d.getTime())) return null;
  const y = d.getUTCFullYear();
  if (y < 1990 || y > 2200) return null;
  return d.toISOString();
};
const toLocalDate = (tz, ...candidates) => {
  for (const c of candidates) {
    const iso = parseTs(c);
    if (iso) return new Date(iso).toLocaleDateString('en-CA', { timeZone: tz });
  }
  return null;
};

// GDPR rule 6: meta_data is filtered through a WHITELIST, never a blacklist.
const ORDER_META_KEEP = new Set([
  '_wc_order_attribution_source_type','_wc_order_attribution_utm_source',
  '_wc_order_attribution_utm_medium','_wc_order_attribution_utm_campaign',
  '_wc_order_attribution_utm_content','_wc_order_attribution_utm_id',
  '_wc_order_attribution_utm_term','_wc_order_attribution_referrer',
  '_wc_order_attribution_device_type','_wc_order_attribution_session_count',
  '_wc_order_attribution_session_pages',
  '_woo_pi_data',
  '_packing_box','_packing_box_id','_packed_by','_packing_status',
  'tppl_api','tppl_package_api','tppl_package_status','tppl_package_status_id',
  'tppl_cpl_batch_state','tppl_package_sent',
  '_comgate_method','_comgate_status',
  '_ethia_price_overrides_total','_ethia_price_overrides_summary',
  '_ethia_price_overrides_sources','_ethia_order_card',
  'is_vat_exempt','_wpify_vat_exempt_reason'
]);
const LINE_META_KEEP = new Set([
  '_woo_cost_price','_reduced_stock',
  '_ethia_price_overrides','_ethia_price_override_reason',
  '_ethia_upsell_original_price','_ethia_upsell_discount_percent','_ethia_upsell_offer_type',
  'dog_meal_type','pack_kg'   // rawbark meal plans (not personal data), 2026-09-21
]);

const mv = (arr, key) => {
  const m = (arr || []).find(x => x.key === key);
  return m ? m.value : null;
};
const keepMeta = (arr, set) => (arr || []).filter(m => set.has(m.key))
  .map(m => ({ key: clean(m.key), value: typeof m.value === 'string' ? clean(m.value) : m.value }));

const REVENUE_STATUSES = new Set(['processing', 'completed', 'on-hold']);
const MAX_PAYLOAD = 800000;   // BigQuery's streaming row limit is 1 MB

const inputs = $input.all();
const rows = [];
const skipped = [];

for (let i = 0; i < inputs.length; i++) {
  const ctx = $('Decode secrets').itemMatching(i).json;
  const page = Array.isArray(inputs[i].json.orders) ? inputs[i].json.orders : [];

  for (const o of page) {
    if (!o || !o.id) continue;

    const orderDate = toLocalDate(ctx.timezone, o.date_created_gmt, o.date_created, o.date_paid_gmt);
    if (!orderDate) {
      if (REVENUE_STATUSES.has(o.status)) {
        throw new Error('Order ' + o.id + ' has status "' + o.status + '" but no usable date. '
          + 'Refusing to drop an order that counts as revenue.');
      }
      skipped.push(o.id + ':' + o.status);
      continue;
    }

    const lines = o.line_items || [];
    const costs = lines.map(li => {
      const c = mv(li.meta_data, '_woo_cost_price');
      if (c === null || c === '') return null;
      const unit = Number(c), qty = Number(li.quantity || 0);
      return (Number.isFinite(unit) && Number.isFinite(qty)) ? unit * qty : null;
    });
    const hasImprint = lines.length > 0 && costs.every(c => c !== null);

    const fees = o.fee_lines || [];
    const codFee = fees.find(f => /dob[ií]rk|cash on delivery/i.test(f.name || ''));

    const basePayload = {
      id: o.id, number: clean(o.number), status: clean(o.status), currency: clean(o.currency),
      prices_include_tax: o.prices_include_tax,
      date_created_gmt: parseTs(o.date_created_gmt), date_modified_gmt: parseTs(o.date_modified_gmt),
      date_paid_gmt: parseTs(o.date_paid_gmt), date_completed_gmt: parseTs(o.date_completed_gmt),
      discount_total: o.discount_total, discount_tax: o.discount_tax,
      shipping_total: o.shipping_total, shipping_tax: o.shipping_tax,
      cart_tax: o.cart_tax, total: o.total, total_tax: o.total_tax,
      customer_id: o.customer_id, created_via: clean(o.created_via),
      payment_method: clean(o.payment_method), payment_method_title: clean(o.payment_method_title),
      billing: { country: clean(o.billing?.country), city: clean(o.billing?.city), state: clean(o.billing?.state) },
      line_items: lines.map(li => ({
        id: li.id, product_id: li.product_id, variation_id: li.variation_id,
        sku: clean(li.sku), name: clean(li.name), quantity: li.quantity,
        subtotal: li.subtotal, subtotal_tax: li.subtotal_tax,
        total: li.total, total_tax: li.total_tax,
        meta_data: keepMeta(li.meta_data, LINE_META_KEEP)
      })),
      shipping_lines: (o.shipping_lines || []).map(s => ({ method_id: clean(s.method_id), method_title: clean(s.method_title), total: s.total, total_tax: s.total_tax })),
      fee_lines: fees.map(f => ({ name: clean(f.name), total: f.total, total_tax: f.total_tax })),
      coupon_lines: (o.coupon_lines || []).map(c => ({ code: clean(c.code), discount: c.discount })),
      refunds: (o.refunds || []).map(r => ({ id: r.id, total: r.total })),
      tax_lines: (o.tax_lines || []).map(t => ({ rate_percent: t.rate_percent, tax_total: t.tax_total, shipping_tax_total: t.shipping_tax_total })),
      meta_data: keepMeta(o.meta_data, ORDER_META_KEEP)
    };

    // Every string inside basePayload has already been cleaned individually.
    // JSON.stringify is well-formed -- it escapes lone surrogates itself -- so
    // its output must NOT be cleaned again: doing so can only damage the JSON.
    let payload = JSON.stringify(basePayload);
    if (payload.length > MAX_PAYLOAD) {
      basePayload.meta_data = basePayload.meta_data.filter(m => m.key !== '_woo_pi_data');
      basePayload._truncated = 'dropped _woo_pi_data';
      payload = JSON.stringify(basePayload);
    }
    if (payload.length > MAX_PAYLOAD) {
      payload = JSON.stringify({ id: o.id, _truncated: 'payload exceeded ' + MAX_PAYLOAD + ' bytes' });
    }

    rows.push({
      json: {
        client_id: ctx.client_id,
        ingested_at: INGESTED_AT,
        ingest_source: 'backfill',

        order_id: String(o.id),
        order_number: clean(o.number) ?? '',
        status: clean(o.status) ?? '',
        currency: clean(o.currency) ?? '',
        prices_include_tax: Boolean(o.prices_include_tax),
        order_date: orderDate,

        date_created_gmt: parseTs(o.date_created_gmt),
        date_modified_gmt: parseTs(o.date_modified_gmt),
        date_paid_gmt: parseTs(o.date_paid_gmt),
        date_completed_gmt: parseTs(o.date_completed_gmt),

        total: num(o.total),
        total_tax: num(o.total_tax),
        subtotal_ex_tax: sum(lines, li => li.total),
        shipping_total: num(o.shipping_total),
        shipping_tax: num(o.shipping_tax),
        discount_total: num(o.discount_total),
        discount_tax: num(o.discount_tax),
        fees_total: sum(fees, f => f.total),
        cod_fee: codFee ? num(codFee.total) : null,
        refunds_total: sum(o.refunds, r => Math.abs(Number(r.total || 0))),

        payment_method: clean(o.payment_method) ?? '',
        shipping_method: clean((o.shipping_lines || [])[0]?.method_id) ?? '',
        customer_id: String(o.customer_id ?? ''),
        customer_email: (clean(o.billing?.email) ?? '').toLowerCase().trim(),
        billing_country: clean(o.billing?.country) ?? '',
        billing_city: clean(o.billing?.city) ?? '',
        created_via: clean(o.created_via) ?? '',
        coupon_codes: JSON.stringify((o.coupon_lines || []).map(c => clean(c.code))),

        attribution_source_type: clean(mv(o.meta_data, '_wc_order_attribution_source_type')),
        utm_source: clean(mv(o.meta_data, '_wc_order_attribution_utm_source')),
        utm_medium: clean(mv(o.meta_data, '_wc_order_attribution_utm_medium')),
        utm_campaign: clean(mv(o.meta_data, '_wc_order_attribution_utm_campaign')),
        utm_content: clean(mv(o.meta_data, '_wc_order_attribution_utm_content')),

        cogs_total: hasImprint ? Math.round(costs.reduce((s, c) => s + c, 0) * 1e6) / 1e6 : null,
        packaging_cost: null,
        shipping_cost: null,
        gateway_fee: null,
        has_cost_imprint: hasImprint,

        packing_box_id: clean(mv(o.meta_data, '_packing_box_id')),
        carrier: clean((o.shipping_lines || [])[0]?.method_id) ?? '',
        carrier_status_code: clean(mv(o.meta_data, 'tppl_package_status_id')),

        payload_json: payload
      },
      pairedItem: { item: i }
    });
  }
}

if (skipped.length) console.log('Skipped ' + skipped.length + ' dateless non-revenue order(s): ' + skipped.join(', '));

return rows;

// Re-reads the orders built upstream rather than the raw API pages, so the
// order_date and client_id on a line can never disagree with its order.
const orders = $('Transform orders').all();
const rows = [];

for (let i = 0; i < orders.length; i++) {
  const o = orders[i].json;
  const payload = JSON.parse(o.payload_json);

  for (const li of (payload.line_items || [])) {
    const costMeta = (li.meta_data || []).find(m => m.key === '_woo_cost_price');
    const unitCost = costMeta && costMeta.value !== '' ? Number(costMeta.value) : null;
    const qty = Number(li.quantity || 0);

    rows.push({
      json: {
        client_id: o.client_id,
        ingested_at: o.ingested_at,
        ingest_source: o.ingest_source,
        order_id: o.order_id,
        order_date: o.order_date,
        line_item_id: String(li.id),
        product_id: String(li.product_id ?? ''),
        variation_id: String(li.variation_id ?? ''),
        sku: li.sku ?? '',
        name: li.name ?? '',
        quantity: qty,
        subtotal: li.subtotal === undefined ? null : Number(li.subtotal),
        subtotal_tax: li.subtotal_tax === undefined ? null : Number(li.subtotal_tax),
        total: li.total === undefined ? null : Number(li.total),
        total_tax: li.total_tax === undefined ? null : Number(li.total_tax),
        unit_cost: unitCost,
        line_cost: unitCost === null ? null : unitCost * qty,
        payload_json: JSON.stringify(li)
      },
      pairedItem: { item: i }
    });
  }
}

return rows;

// Paginates WooCommerce orders for each active client.
//
// BACKFILL pages by CREATION date from a fixed start. Modification date is
// unusable for this: over 100 of Ethia's orders share a date_modified_gmt
// inside one 8-second bulk edit, so a modified_after cursor lands inside that
// cluster and never advances -- three consecutive runs re-fetched the same 100
// orders. Creation dates do not collapse that way.
//
// CRON pages by modified_after, which is what an incremental run needs: an
// order refunded today must be picked up even though it was created months ago.
//
// BACKFILL flipped to false on 2026-09-21 once both histories were loaded
// (ethia via this node on 2026-09-20; rawbark, 51,481 orders = X-WP-Total, via
// infra/woo_backfill.mjs from Cloud Shell). Load a NEW client's history with that
// script, not by flipping this back: one run holds every order in one n8n item
// and stops at MAX_PAGES without raising. $execution.mode is NOT usable to decide
// this -- it does not return 'manual' for an API-triggered run.
const BACKFILL = false;

const helpers = this.helpers;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const PER_PAGE    = 100;
const PAGE_PAUSE  = 1100;   // ~1 req/s, shared hosting
const MAX_PAGES   = 200;
const MAX_RETRIES = 4;      // 2s, 4s, 8s, 16s

const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const ctx = $('Decode secrets').itemMatching(i).json;
  const cursorParam = BACKFILL ? 'after' : 'modified_after';
  const orderBy     = BACKFILL ? 'date'  : 'modified';
  const cursorValue = BACKFILL ? (inputs[i].json.created_after || '2025-01-01T00:00:00')
                               : inputs[i].json.modified_after;

  const orders = [];
  let page = 1;
  let requests = 0;
  let reportedTotal = null;

  while (page <= MAX_PAGES) {
    const url = ctx.base_url + '/wp-json/wc/v3/orders'
      + '?' + cursorParam + '=' + encodeURIComponent(cursorValue)
      + '&dates_are_gmt=true&status=any&orderby=' + orderBy + '&order=asc'
      + '&per_page=' + PER_PAGE + '&page=' + page;

    let r;
    let attempt = 0;
    while (true) {
      r = await helpers.httpRequest({
        method: 'GET', url,
        headers: { Authorization: 'Basic ' + ctx.auth_b64, Accept: 'application/json' },
        returnFullResponse: true, json: true,
        ignoreHttpStatusErrors: true, timeout: 60000
      });
      requests++;

      if (r.statusCode === 429 || r.statusCode >= 500) {
        attempt++;
        if (attempt > MAX_RETRIES) {
          throw new Error('WooCommerce kept returning ' + r.statusCode + ' for ' + ctx.client_id
            + ' after ' + MAX_RETRIES + ' retries (page ' + page + ').');
        }
        await sleep(2000 * Math.pow(2, attempt - 1));
        continue;
      }
      break;
    }

    if (reportedTotal === null && r.headers && r.headers['x-wp-total']) {
      reportedTotal = Number(r.headers['x-wp-total']);
    }

    const body = r.body;
    if (body && body.code && body.data && typeof body.data.status === 'number') {
      throw new Error('WooCommerce API returned ' + body.data.status + ' (' + body.code + '): '
        + (body.message || '') + ' -- no orders were loaded for ' + ctx.client_id + '.');
    }
    if (!Array.isArray(body)) {
      throw new Error('WooCommerce returned an unexpected body type for ' + ctx.client_id
        + ' on page ' + page + ': ' + typeof body);
    }

    orders.push(...body);
    if (body.length < PER_PAGE) break;

    page++;
    await sleep(PAGE_PAUSE);
  }

  out.push({
    json: {
      client_id: ctx.client_id,
      mode: BACKFILL ? 'backfill' : 'cron',
      cursor_param: cursorParam,
      cursor_value: cursorValue,
      reported_total: reportedTotal,
      requests, pages: page,
      order_count: orders.length,
      orders
    },
    pairedItem: { item: i }
  });
}

return out;
